const KEY="ccems_live_v01";
const colours=["White / Cream","Ivory","Pale Beige","Tan","Rich Brown","Dark Chocolate","Blue","Blue Green","Olive Green","Speckled"];
const eggColours=["#eee9d8","#e5d4aa","#d9b47d","#b87242","#7e401f","#422318","#8bb2ba","#77a59c","#7f8750","#c5aa72"];
const collections=["Spring Heritage Egg Collection","Summer Heritage Egg Collection","Harvest Heritage Egg Collection","Christmas Estate Heritage Egg Collection","Royal Estate / Heritage Reserve Collection"];
let view="standby",selectedHouse=0,menuOpen=false,houseMenuOpen=false,collectionPhoto=null,collectionStartedAt=null,concernType="",concernPhoto=null,concernLocation=0,concernLocationMenuOpen=false,concernDescription="",journalFilter="all",selectedJournalRecord=null,counts=Object.fromEntries(colours.map(c=>[c,0]));
const concernLocations=["House 1 — Spring Heritage","House 2 — Summer Heritage","House 3 — Harvest Heritage","House 4 — Christmas Estate","House 5 — Royal Estate Reserve","Collection Pavilion","Estate Operations Yard","Other estate area"];
let liveWeather={temperature:18,code:1,isDay:1,updatedAt:null,live:false};
const app=document.getElementById("fieldApp");
function chooseCollectionPhoto(input){const file=input.files&&input.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{collectionPhoto={name:file.name,data:reader.result};render()};reader.readAsDataURL(file)}function state(){try{return JSON.parse(localStorage.getItem(KEY)||"{}")}catch{return {}}}function save(s){localStorage.setItem(KEY,JSON.stringify(s))}function go(v){view=v;menuOpen=false;render();requestAnimationFrame(()=>scrollTo(0,0))}function toggleMenu(){menuOpen=!menuOpen;render()}function total(){return Object.values(counts).reduce((a,b)=>a+b,0)}function change(c,d){const y=scrollY;counts[c]=Math.max(0,(counts[c]||0)+d);render();requestAnimationFrame(()=>scrollTo(0,y))}
function verse(){const a=window.CCEMS_DAILY_VERSES||[["Commit your deeds to the LORD, and your plans shall succeed.","PROVERBS 16:3"]],start=Date.UTC(new Date().getUTCFullYear(),0,0),day=Math.floor((Date.now()-start)/864e5);const selected=a[day%a.length];return[selected[0],`${selected[1]} · WEBPB`]}
function weatherCondition(code){if(code===0)return'Clear sky';if(code<=3)return'Partly cloudy';if(code<=48)return'Foggy';if(code<=57)return'Drizzle';if(code<=67)return'Rain';if(code<=77)return'Snow';if(code<=82)return'Rain showers';if(code<=86)return'Snow showers';return'Thunderstorms'}function weatherIconClass(code,isDay){if(!isDay&&code<=3)return'weather-night';if(code===0)return'weather-clear';if(code<=3)return'weather-cloud';if(code<=48)return'weather-fog';if(code<=67||code<=82)return'weather-rain';if(code<=77||code<=86)return'weather-snow';return'weather-storm'}function weatherUpdated(){return liveWeather.updatedAt?`Updated ${new Date(liveWeather.updatedAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}`:'Offline estimate'}function applyLiveWeather(){const condition=weatherCondition(liveWeather.code),iconClass=weatherIconClass(liveWeather.code,liveWeather.isDay);document.querySelectorAll('.field-greeting>aside').forEach(card=>{card.classList.add('live-weather');card.classList.toggle('weather-live',liveWeather.live);const iconEl=card.querySelector('span'),tempEl=card.querySelector('b'),conditionEl=card.querySelector('small');let updatedEl=card.querySelector('.weather-updated');if(!updatedEl){card.insertAdjacentHTML('beforeend','<em class="weather-updated"></em>');updatedEl=card.querySelector('.weather-updated')}if(iconEl){iconEl.textContent='';iconEl.className=`weather-line-icon ${iconClass}`;iconEl.setAttribute('aria-label',condition)}if(tempEl)tempEl.textContent=`${Math.round(liveWeather.temperature)}°C`;if(conditionEl)conditionEl.textContent=condition;if(updatedEl)updatedEl.textContent=`Royal Tunbridge Wells · ${weatherUpdated()}`});document.querySelectorAll('.journal-live-status>div:first-child').forEach(card=>{const temp=card.querySelector('b'),conditionText=card.querySelector('small');if(temp)temp.textContent=`${Math.round(liveWeather.temperature)}°C`;if(conditionText)conditionText.textContent=condition})}async function loadLiveWeather(){try{const cached=JSON.parse(localStorage.getItem('ccems_tunbridge_weather')||'null');if(cached?.updatedAt){liveWeather=cached;applyLiveWeather()}const response=await fetch('https://api.open-meteo.com/v1/forecast?latitude=51.1332&longitude=0.2626&current=temperature_2m,weather_code,is_day&timezone=Europe%2FLondon');if(!response.ok)throw new Error('Weather unavailable');const data=await response.json(),current=data.current;if(!current)throw new Error('Weather unavailable');liveWeather={temperature:current.temperature_2m,code:current.weather_code,isDay:current.is_day,updatedAt:Date.now(),live:true};localStorage.setItem('ccems_tunbridge_weather',JSON.stringify(liveWeather));applyLiveWeather()}catch{applyLiveWeather()}}
function crest(){return `<img class="crest approved-crest" src="crown-cross-monogram-approved.png" alt="Crown and Cross approved crest">`}function cross(){return `<div class="ornament safety-faith-mark" aria-label="Faith and safety"><span>†</span></div>`}function back(label,target){return `<button class="back" onclick="go('${target}')">← <span>${label}</span></button>`}function journalHead(title,target="home"){return `<header class="journal-head">${back("Back",target)}<div><small>CROWN & CROSS FIELD JOURNAL</small><h1>${title}</h1></div>${crest()}</header>`}
function standby(){const now=new Date(),time=now.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),date=now.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'});return `<section class="field-standby enter-anywhere" role="button" tabindex="0" aria-label="Tap anywhere to continue" onclick="go('welcome')" onkeydown="if(event.key==='Enter'||event.key===' '){go('welcome')}"><div class="standby-brand">${crest()}<h1>Crown &amp; Cross</h1><p>Organic Estate</p></div><article class="standby-panel"><time>${time}</time><p class="standby-date">${date}</p><div class="faith-divider"><span>†</span></div><blockquote>“Commit your work to the Lord,<br>and your plans will be established.”</blockquote><cite>Proverbs 16:3</cite><div class="standby-sheaves" aria-hidden="true"><img src="faith-botanical-divider-v1.png" alt=""></div><small>Tap anywhere to continue</small></article></section>`}
function welcome(){return `<section class="field-welcome"><div class="welcome-photo" role="img" aria-label="Crown and Cross estate at sunrise"><button class="welcome-back" aria-label="Back to standby" onclick="go('standby')">←</button></div><article class="welcome-arch"><div class="welcome-cross">†</div><p class="welcome-kicker">Crown &amp; Cross Organic Estate</p><h1>Welcome<br>to the Estate</h1><p class="welcome-motto">Stewardship · Faith · Excellence</p><img class="welcome-ornament" src="faith-botanical-divider-v1.png" alt=""><div class="welcome-actions"><button class="journal-primary" onclick="go('login')">Let’s Begin <span>→</span></button><button class="journal-secondary" onclick="go('setup')">Set Up This Device</button></div></article></section>`}
function login(){return `<section class="field-login"><button class="login-back" aria-label="Back to Welcome" onclick="go('welcome')">←</button><aside class="login-estate" role="img" aria-label="Crown and Cross estate at sunrise"><div class="login-estate-brand"><img class="crest login-approved-crest" src="crown-cross-monogram-approved.png" alt="Crown and Cross approved crest"><strong>Crown &amp; Cross</strong><span>Organic Estate</span></div><blockquote>“Commit your work to the Lord,<br>and your plans will be established.”<cite>Proverbs 16:3</cite></blockquote></aside><main class="login-paper"><div class="login-brand-real"><img class="crest login-approved-crest" src="crown-cross-monogram-approved.png" alt="Crown and Cross approved crest"><p>Crown &amp; Cross</p><small>Estate Field Journal</small></div><form class="login-form-real" onsubmit="event.preventDefault();go('home')"><div class="login-faith-mark">†</div><p class="login-kicker">Secure Estate Access</p><h1>Sign In</h1><p class="login-intro">Please sign in to continue to your field day.</p><label><span>Employee ID or email</span><div class="login-input"><b aria-hidden="true">♙</b><input autocomplete="username" value="Dean" required></div></label><label><span>Password</span><div class="login-input"><b aria-hidden="true">▣</b><input type="password" autocomplete="current-password" value="ccems" required><button type="button" aria-label="Show password" onclick="const i=this.previousElementSibling;i.type=i.type==='password'?'text':'password'">◉</button></div></label><div class="login-options"><label><input type="checkbox"> Remember this approved device</label><button type="button">Forgot password?</button></div><button class="journal-primary login-submit">Sign In <span>→</span></button><button type="button" class="login-biometric" onclick="go('home')">Use Secure PIN or Face ID</button><div class="secure-note"><span>♢</span><p><strong>Secure access</strong><small>All estate information is encrypted and protected.</small></p></div></form><img class="login-botanical" src="faith-botanical-divider-v1.png" alt=""></main></section>`}
function setup(){return `<section class="paper-page">${back("Welcome","welcome")}<div class="login-brand">${crest()}<small>APPROVED DEVICE REGISTRATION</small></div><article class="paper-card setup-card">${cross()}<h1>Set Up This Device</h1>${[[1,"Identify this device","Give this phone or tablet an estate name."],[2,"Supervisor approval","Confirm the employee assigned to it."],[3,"Secure access","Enable a PIN or supported biometric access."]].map(x=>`<div class="setup-step"><b>${x[0]}</b><span><strong>${x[1]}</strong><small>${x[2]}</small></span></div>`).join("")}<button class="journal-primary" onclick="alert('Secure device approval will be connected during deployment.')">Begin Setup <span>→</span></button><button class="journal-secondary" onclick="go('welcome')">Not Now — Return to Welcome</button></article></section>`}
function homeStats(){const s=state(),now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`,isToday=x=>(x?.createdAt||x?.date||'').slice(0,10)===today,collectionsToday=(s.eggCollections||[]).filter(isToday),safetyToday=(s.preTaskSafety||[]).filter(isToday),concernsToday=(s.concerns||[]).filter(isToday),times=collectionsToday.map(x=>x.createdAt).filter(Boolean).sort(),firstTime=times.length?new Date(times[0]).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):'Not recorded',pendingForms=(s.safetyForms||[]).filter(x=>x.status==='Awaiting supervisor review').length,activeConcerns=(s.concerns||[]).filter(x=>x.status==='Supervisor alerted').length,statuses=[safetyToday.length?'Completed':'Not started',collectionsToday.length?'Completed':'Not started','Scheduled',concernsToday.length?'Completed':'Available'],completed=statuses.filter(x=>x==='Completed').length;return{tasks:4,firstCollection:firstTime,alerts:pendingForms+activeConcerns,urgent:activeConcerns,statuses,completed}}
function enhanceFieldDay(){if(view!=='home')return;const stats=homeStats(),cards=[...document.querySelectorAll('.field-tasks>button')],statusClass=x=>x.toLowerCase().replaceAll(' ','-');cards.forEach((card,i)=>{const status=stats.statuses[i];card.classList.toggle('task-completed',status==='Completed');card.querySelector('.task-status')?.remove();card.querySelector('span')?.insertAdjacentHTML('beforeend',`<mark class="task-status status-${statusClass(status)}">${status}</mark>`)});const heading=document.querySelector('.section-heading');heading?.querySelector('.day-progress')?.remove();heading?.insertAdjacentHTML('afterend',`<section class="day-progress"><div><span style="width:${stats.completed/4*100}%"></span></div><small>${stats.completed} of 4 completed</small></section>`);const headerAlert=document.querySelector('.field-alert span');if(headerAlert){headerAlert.textContent=stats.urgent;headerAlert.parentElement.classList.toggle('no-urgent-alerts',stats.urgent===0);headerAlert.parentElement.setAttribute('aria-label',stats.urgent?`Open ${stats.urgent} urgent alert${stats.urgent===1?'':'s'}`:'No urgent alerts')};const first=document.querySelector('.live-summary button:nth-child(2) strong');first?.classList.toggle('not-recorded',stats.firstCollection==='Not recorded')}
function home(){const v=verse(),now=new Date(),hour=now.getHours(),greeting=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening',date=new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now),workday=now.toLocaleDateString('en-GB',{weekday:'long'}).toUpperCase()+"’S WORK";return `<section class="field-day"><div class="field-day-bg" aria-hidden="true"></div><header class="field-day-head"><button class="field-menu" aria-label="Open menu" onclick="toggleMenu()">☰</button><div class="field-day-title">${crest()}<small>Crown &amp; Cross Estate Field Journal</small><h1>My Field Day</h1><p>${date} · <time>${now.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</time></p></div><button class="field-alert" aria-label="Open priority alerts" onclick="go('forms')"><span>${homeStats().alerts}</span><i class="alert-crown" aria-hidden="true"></i></button></header><aside class="field-drawer ${menuOpen?'open':''}"><div class="drawer-engraving" aria-hidden="true"></div><div class="drawer-head">${crest()}<div><small>CROWN &amp; CROSS</small><strong>Estate Navigation</strong><em>Field Journal</em></div><button aria-label="Close menu" onclick="toggleMenu()">×</button></div><nav><section class="drawer-group"><header><span>MY ESTATE DAY</span><i class="drawer-crown" aria-hidden="true"></i></header><button class="drawer-link active" onclick="go('home')"><i class="drawer-icon drawer-home"></i><span><strong>My Field Day</strong><small>Today’s estate work</small></span></button><button class="drawer-link" onclick="go('tasks')"><i class="drawer-icon drawer-tasks"></i><span><strong>Assigned Tasks</strong><small>Work and priorities</small></span></button><button class="drawer-link" onclick="go('journal')"><i class="drawer-icon drawer-journal"></i><span><strong>Field Journal</strong><small>Submitted records</small></span></button></section><div class="drawer-faith-divider"><span>†</span></div><section class="drawer-group"><header><span>HERITAGE EGGS</span><i class="drawer-crown" aria-hidden="true"></i></header><button class="drawer-link" onclick="go('collect')"><i class="drawer-icon drawer-egg"></i><span><strong>Egg Collection</strong><small>Ten-colour entry</small></span></button><button class="drawer-link" onclick="go('task')"><i class="drawer-icon drawer-shield"></i><span><strong>Pre-task Safety</strong><small>Safety confirmation</small></span></button></section><section class="drawer-group"><header><span>ESTATE RECORDS</span><i class="drawer-crown" aria-hidden="true"></i></header><button class="drawer-link" onclick="go('forms')"><i class="drawer-icon drawer-forms"></i><span><strong>Safety Forms</strong><small>Compliance records</small></span></button><button class="drawer-link" onclick="go('concern')"><i class="drawer-icon drawer-concern"></i><span><strong>Report a Concern</strong><small>Hazards and observations</small></span></button><button class="drawer-link" onclick="go('more')"><i class="drawer-icon drawer-more"></i><span><strong>More &amp; Settings</strong><small>Device and access</small></span></button></section></nav><article class="drawer-verse"><small>TODAY’S VERSE</small><p>“Whatever you do, work at it with all your heart.”</p><b>COLOSSIANS 3:23</b></article><footer>${crest()}<div><strong>Crown &amp; Cross Organic Estate</strong><small>Faith · Family · Farm · Future</small></div></footer></aside><button class="drawer-shade ${menuOpen?'show':''}" aria-label="Close menu" onclick="toggleMenu()"></button><main class="field-day-content"><article class="field-greeting"><div><small>${greeting},</small><strong>Dean</strong><em>Estate Director</em></div><aside><span>☀</span><b>18°C</b><small>Partly sunny</small></aside></article><section class="day-summary live-summary"><button onclick="go('tasks')" aria-label="Open today’s assigned tasks"><span class="summary-task-icon"></span><strong>${homeStats().tasks}</strong><small>Tasks today</small></button><button onclick="go('collect')" aria-label="Open egg collection"><span class="summary-clock-icon"></span><strong>${homeStats().firstCollection}</strong><small>First collection</small></button><button onclick="go('forms')" aria-label="Open priority safety alerts"><span class="summary-alert-icon">!</span><strong>${homeStats().alerts}</strong><small>Priority alert${homeStats().alerts===1?'':'s'}</small></button></section><div class="section-heading"><div><small>${workday}</small><h2>Today’s Tasks</h2></div><button onclick="go('tasks')">View all</button></div><section class="field-tasks"><button onclick="go('task')"><i class="task-icon egg-task">◉</i><span><small>HERITAGE EGGS</small><strong>Pre-task safety</strong><em>Confirm safety and begin collection</em></span><b>›</b></button><button onclick="go('collect')"><i class="task-icon collection-task">◒</i><span><small>EGG COLLECTION</small><strong>Ten-colour entry</strong><em>Record today’s house totals</em></span><b>›</b></button><button onclick="go('tasks')"><i class="task-icon welfare-task">♡</i><span><small>ANIMAL WELFARE</small><strong>Livestock checks</strong><em>Open today’s assigned work</em></span><b>›</b></button><button onclick="go('concern')"><i class="task-icon concern-task">!</i><span><small>ESTATE REPORTING</small><strong>Report a concern</strong><em>Log a hazard, issue or observation</em></span><b>›</b></button></section><article class="field-verse"><div class="mini-cross">†</div><small>TODAY’S VERSE</small><p>“${v[0]}”</p><b>${v[1]}</b></article><div class="field-landscape" aria-hidden="true"><img src="field-estate-panorama-approved-v3.png" alt=""></div></main><nav class="field-bottom-nav"><button class="active" onclick="go('home')"><i class="nav-icon nav-home" aria-hidden="true"></i><span>My Day</span></button><button onclick="go('tasks')"><i class="nav-icon nav-tasks" aria-hidden="true"></i><span>Tasks</span></button><button onclick="go('journal')"><i class="nav-icon nav-journal" aria-hidden="true"></i><span>Journal</span></button><button onclick="go('more')"><i class="nav-icon nav-more" aria-hidden="true"></i><span>More</span></button></nav></section>`}
function tasks(){return `<section class="journal-page">${journalHead("Assigned Tasks")}<main class="paper-workflow"><h2>Today’s Assigned Tasks</h2><p>Your active estate work for today.</p><section class="task-list"><button onclick="go('task')"><i>◉</i><span><strong>Heritage Eggs</strong><small>Pre-task safety</small></span><b>›</b></button><button onclick="go('collect')"><i>◒</i><span><strong>Egg Collection</strong><small>Ten-colour entry</small></span><b>›</b></button><button onclick="go('concern')"><i>!</i><span><strong>Report a Concern</strong><small>Hazards and observations</small></span><b>›</b></button></section></main></section>`}
function collectionArtworkIndex(name=''){return /spring/i.test(name)?0:/summer/i.test(name)?1:/harvest/i.test(name)?2:/christmas/i.test(name)?3:4}function setJournalFilter(filter){journalFilter=filter;render();requestAnimationFrame(()=>scrollTo(0,0))}function journalRecords(){const s=state(),records=[];(s.eggCollections||[]).forEach(r=>records.push({kind:'eggs',title:r.collection||'Heritage Egg Collection',reference:r.id||'Egg collection',amount:`${r.quantity||0} eggs`,status:'Recorded',createdAt:r.createdAt||r.date,worker:r.worker||'Estate team',photo:!!r.photo,artwork:collectionArtworkIndex(r.collection),raw:r}));(s.preTaskSafety||[]).forEach(r=>records.push({kind:'safety',title:'Heritage Eggs Pre-Task Safety',reference:r.reference,amount:'All confirmations completed',status:r.status||'Confirmed',createdAt:r.createdAt,worker:r.worker||'Estate team',raw:r}));(s.safetyForms||[]).forEach(r=>records.push({kind:'safety',title:r.title||'Safety Record',reference:r.reference,amount:r.department||'Estate compliance',status:r.status||'Submitted',createdAt:r.createdAt||r.date,worker:r.worker||'Estate team',raw:r}));(s.concerns||[]).forEach(r=>records.push({kind:'concern',title:(r.type||'Estate concern').replace(/\b\w/g,c=>c.toUpperCase()),reference:r.reference,amount:r.location||'Estate location',status:r.status||'Submitted',createdAt:r.createdAt,worker:r.worker||'Estate team',photo:!!r.photo,raw:r}));return records.sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0))}function openJournalRecord(index){selectedJournalRecord=journalRecords()[index]||null;if(selectedJournalRecord)go('journal-detail')}function journalV47(){const all=journalRecords(),rows=(journalFilter==='all'?all:all.filter(r=>r.kind===journalFilter)),today=new Date().toISOString().slice(0,10),todayCount=all.filter(r=>(r.createdAt||'').slice(0,10)===today).length,formatDate=v=>{if(!v)return 'Date not recorded';const d=new Date(v);return isNaN(d)?v:new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)};return `<section class="journal-page">${journalHead("My Field Journal")}<main class="paper-workflow field-journal-v47"><div class="journal-v47-heading"><div class="journal-book-seal" aria-hidden="true"><i></i></div><small>ESTATE RECORDS</small><h2>Submitted Records</h2><div class="pretask-divider" aria-hidden="true"><span></span></div><p>A secure record of work submitted from this approved estate device.</p></div><section class="journal-summary"><article><strong>${todayCount}</strong><span>Submitted today</span></article><article><strong>${all.length}</strong><span>Total records</span></article><article><strong>Dean</strong><span>Approved user</span></article></section><nav class="journal-filters" aria-label="Filter submitted records">${[['all','All'],['eggs','Eggs'],['safety','Safety'],['concern','Concerns']].map(([key,label])=>`<button class="${journalFilter===key?'active':''}" aria-pressed="${journalFilter===key}" onclick="setJournalFilter('${key}')">${label}</button>`).join('')}</nav><section class="journal-v47-records">${rows.length?rows.map(r=>`<button class="record-card record-${r.kind}" onclick="openJournalRecord(${all.indexOf(r)})"><i class="record-icon ${r.kind==='eggs'?'collection-artwork art-'+r.artwork:''}" aria-hidden="true"></i><div><small>${r.kind==='eggs'?'HERITAGE EGGS':r.kind==='safety'?'SAFETY & COMPLIANCE':'ESTATE CONCERN'}</small><h3>${r.title}</h3><p>${r.amount}</p><footer><span>${formatDate(r.createdAt)}</span><b>${r.status}</b></footer><em>${r.reference||'Reference pending'} · ${r.worker}${r.photo?' · Photograph attached':''}</em></div><span class="record-chevron" aria-hidden="true">›</span></button>`).join(''):`<div class="journal-empty"><i></i><h3>No ${journalFilter==='all'?'submitted':journalFilter} records yet</h3><p>Completed entries will appear here automatically.</p></div>`}</section><button class="journal-secondary journal-home-button" onclick="go('home')">Back to My Day</button></main></section>`}
function journalDetailV48(){const r=selectedJournalRecord;if(!r)return journalV47();const x=r.raw||{},date=(()=>{const d=new Date(r.createdAt||0);return isNaN(d)?'Date not recorded':new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)})(),details=r.kind==='eggs'?`<section class="detail-colours"><h3>Ten-Colour Collection</h3>${colours.map((c,i)=>`<div><i class="egg" style="--egg:${eggColours[i]}"></i><span>${c}</span><strong>${x.colours?.[c]||0}</strong></div>`).join('')}<footer><span>Total Eggs</span><strong>${x.quantity||0}</strong></footer></section>`:r.kind==='concern'?`<section class="detail-panel"><h3>Concern Details</h3><dl><div><dt>Category</dt><dd>${r.title}</dd></div><div><dt>Location</dt><dd>${x.location||'Not recorded'}</dd></div><div><dt>Description</dt><dd>${x.description||'No description supplied'}</dd></div></dl></section>`:`<section class="detail-panel"><h3>Safety Confirmation</h3><dl><div><dt>Department</dt><dd>${x.department||'Heritage Eggs'}</dd></div><div><dt>Confirmations</dt><dd>${x.confirmations?`${x.confirmations} completed`:'Form submitted'}</dd></div><div><dt>Review status</dt><dd>${r.status}</dd></div></dl></section>`;return `<section class="journal-page">${journalHead("Record Details","journal")}<main class="paper-workflow journal-detail-v48"><div class="detail-heading">${r.kind==='eggs'?'<div class="collection-detail-art art-'+r.artwork+'" role="img" aria-label="'+r.title+' approved collection artwork"></div>':'<i class="record-icon record-'+r.kind+'" aria-hidden="true"></i>'}<small>${r.kind==='eggs'?'HERITAGE EGGS':r.kind==='safety'?'SAFETY & COMPLIANCE':'ESTATE CONCERN'}</small><h2>${r.title}</h2><div class="pretask-divider"><span></span></div><b>${r.status}</b></div><section class="detail-meta"><div><small>REFERENCE</small><strong>${r.reference||'Pending'}</strong></div><div><small>SUBMITTED BY</small><strong>${r.worker}</strong></div><div><small>DATE & TIME</small><strong>${date}</strong></div></section>${details}${x.photo?.data?`<figure class="detail-photo"><img src="${x.photo.data}" alt="Photograph attached to ${r.title}"><figcaption>${x.photo.name||'Attached photograph'}</figcaption></figure>`:''}<section class="detail-audit"><i></i><div><small>AUDIT STATUS</small><strong>Securely recorded on this approved device</strong><span>Available to authorised estate management.</span></div></section><button class="journal-primary detail-back" onclick="go('journal')">Back to My Field Journal</button></main></section>`}
function more(){return `<section class="journal-page">${journalHead("More & Settings")}<main class="paper-workflow"><h2>Field Tools</h2><section class="task-list"><button onclick="go('setup')"><i>◇</i><span><strong>Device Setup</strong><small>Approved device registration</small></span><b>›</b></button><button onclick="go('forms')"><i class="forms-hub-icon">+</i><span><strong>Safety Forms & Records</strong><small>Risk, equipment, COSHH, training and incidents</small></span><b>›</b></button><button onclick="go('concern')"><i>!</i><span><strong>Report a Concern</strong><small>Safety, welfare and estate issues</small></span><b>›</b></button><button onclick="go('welcome')"><i>←</i><span><strong>Sign Out</strong><small>Return to the Welcome page</small></span><b>›</b></button></section></main></section>`}function task(){const checks=["I am fit for work and free from illness or injury.","I have read today’s estate safety procedures.","PPE is clean and in good order.","I will handle hens and eggs with care and respect.","Biosecurity standards will be maintained.","I will report hazards without delay."];return `<section class="journal-page">${journalHead("Heritage Eggs — Pre-Task Safety")}<main class="paper-workflow">${cross()}<h2>Safety First</h2><p>Please read and confirm each item before proceeding.</p><div class="journal-checks">${checks.map(x=>`<label><input type="checkbox" checked><span>${x}</span></label>`).join("")}</div><button class="journal-primary" onclick="go('collect')">I Confirm & Continue <span>→</span></button><button class="text-button" onclick="go('home')">Back to My Field Day</button></main></section>`}
function collect(){return `<section class="journal-page">${journalHead("Heritage Eggs — Daily Collection","task")}<main class="paper-workflow collection"><p>Select the house, then enter each egg colour collected.</p><select class="house-select" onchange="selectedHouse=this.selectedIndex">${collections.map((x,i)=>`<option ${i===selectedHouse?'selected':''}>House ${i+1} — ${x.replace(' Egg Collection','')}</option>`).join("")}</select><section class="egg-rows">${colours.map((c,i)=>`<div><i class="egg" style="--egg:${eggColours[i]}"></i><strong>${c}</strong><button onclick="change('${c}',-1)">−</button><input inputmode="numeric" value="${counts[c]}" onchange="counts['${c}']=Math.max(0,+this.value||0);render()"><button onclick="change('${c}',1)">+</button></div>`).join("")}</section><div class="collection-total"><span>Total Eggs</span><strong>${total()}</strong></div><label class="journal-field">Notes<textarea placeholder="Optional collection notes"></textarea></label><label class="photo-upload journal-secondary"><input type="file" accept="image/*" capture="environment" onchange="chooseCollectionPhoto(this)"><span>Add Photograph</span></label>${collectionPhoto?`<figure class="photo-preview"><img src="${collectionPhoto.data}" alt="Selected collection photograph"><figcaption>${collectionPhoto.name}</figcaption><button type="button" onclick="collectionPhoto=null;render()">Remove</button></figure>`:``}<button class="journal-primary" onclick="submitCollection()">Review & Submit <span>→</span></button></main></section>`}
function submitCollection(){if(!total())return alert("Enter at least one collected egg.");const s=state(),id="HEG-"+Date.now();s.eggCollections=s.eggCollections||[];s.eggCollections.unshift({id,collection:collections[selectedHouse],quantity:total(),colours:{...counts},date:new Date().toISOString().slice(0,10),source:"CCEMS Field App",worker:"Dean",createdAt:new Date().toISOString(),photo:collectionPhoto?{name:collectionPhoto.name,data:collectionPhoto.data}:null});s.audit=s.audit||[];s.audit.unshift({ts:new Date().toISOString(),action:"FIELD_EGG_COLLECTION",detail:`${collections[selectedHouse]} · ${total()} eggs · Dean`});save(s);window.lastBatch=id;go("confirm")}
function concern(){return `<section class="journal-page">${journalHead("Report a Concern")}<main class="paper-workflow concern"><p>What would you like to report?</p><div class="concern-types">${[["♧","Animal Welfare"],["⌾","Biosecurity"],["⚒","Equipment"],["△","Health & Safety"],["","Environment"],["•••","Other"]].map(x=>`<button><i class="${x[1]==='Environment'?'environment-leaf':''}">${x[0]}</i><span>${x[1]}</span></button>`).join("")}</div><label class="journal-field">Location<select><option>House 1 — Spring Heritage</option><option>Other estate area</option></select></label><label class="journal-field">Description<textarea placeholder="What happened? Where? Are there immediate risks?"></textarea></label><button class="journal-secondary">Add Photograph</button><button class="journal-primary" onclick="alert('Concern submitted and supervisor alerted.');go('home')">Submit Report <span>→</span></button></main></section>`}
function confirm(){return `<section class="confirmation">${crest()}<div class="seal-check">✓</div><h1>Collection<br>Submitted</h1><p>Thank you, Dean.<br>Your egg collection has been recorded.</p><article><span>Collection ID<b>${window.lastBatch||'Recorded'}</b></span><span>Total Eggs<b>${total()}</b></span><span>House<b>${selectedHouse+1}</b></span></article><button class="journal-primary" onclick="go('home')">Back to My Field Day <span>→</span></button><button class="journal-secondary" onclick="counts=Object.fromEntries(colours.map(c=>[c,0]));go('collect')">Record Another Collection</button></section>`}

const safetyFormTypes={
 risk:{title:"Risk Assessment",intro:"Identify hazards, who may be harmed, controls and review arrangements.",fields:[["Activity or task","text"],["Estate location","text"],["Hazards identified","textarea"],["Who may be harmed and how","textarea"],["Existing control measures","textarea"],["Further actions required","textarea"],["Responsible person","text"],["Action due date","date"],["Review date","date"]]},
 equipment:{title:"Equipment Inspection",intro:"Record a daily or routine safety inspection before equipment is used.",fields:[["Equipment type","text"],["Asset or registration number","text"],["Estate location","text"],["Guards and safety devices","select"],["Tyres, brakes and steering","select"],["Hydraulics, electrics and controls","select"],["Defects identified","textarea"],["Action taken / equipment isolated","textarea"],["Next inspection date","date"]]},
 coshh:{title:"COSHH Assessment",intro:"Assess hazardous substances using the supplier label and current safety data sheet.",fields:[["Substance or product","text"],["Supplier / manufacturer","text"],["Safety data sheet reference","text"],["Work activity and quantity used","textarea"],["Health hazards and exposure routes","textarea"],["People at risk","textarea"],["Controls, ventilation and hygiene","textarea"],["Required PPE","text"],["Storage and disposal arrangements","textarea"],["Emergency / first-aid measures","textarea"],["Review date","date"]]},
 training:{title:"Training & Induction Record",intro:"Record the briefing, instruction or competency assessment completed.",fields:[["Worker name","text"],["Role / department","text"],["Training or induction topic","text"],["Trainer / assessor","text"],["Training date","date"],["Topics and practical instruction covered","textarea"],["Competency outcome","select"],["Further training or restrictions","textarea"],["Renewal / review date","date"]]},
 incident:{title:"Accident, Incident & Near-Miss Report",intro:"Record injuries, near misses and dangerous occurrences promptly.",fields:[["Event type","event"],["Date of event","date"],["Time of event","time"],["Estate location","text"],["Person(s) involved","text"],["What happened","textarea"],["Injury or potential harm","textarea"],["Immediate action taken","textarea"],["Witnesses","text"],["Manager notified","select"],["Further investigation / RIDDOR review","textarea"]]}
};
function forms(){const s=state(),rows=(s.safetyForms||[]).slice(0,6);return `<section class="journal-page">${journalHead("Safety Forms & Records","more")}<main class="paper-workflow safety-forms-hub"><p class="forms-intro">Complete and retain the estate's core health and safety records.</p><section class="safety-form-list">${Object.entries(safetyFormTypes).map(([k,f],i)=>`<button onclick="go('form-${k}')"><i>${i+1}</i><span><strong>${f.title}</strong><small>${f.intro}</small></span><b>›</b></button>`).join("")}</section><h2>Recent Safety Records</h2><section class="journal-records">${rows.length?rows.map(r=>`<article><strong>${r.title}</strong><span>${r.reference}</span><small>${r.worker} · ${r.date} · ${r.status}</small></article>`).join(""):'<article><strong>No safety forms submitted yet</strong><small>Completed forms will appear here and in the main compliance record.</small></article>'}</section><p class="compliance-note">Templates support estate record-keeping and must be reviewed by a competent person where the risk or regulation requires it.</p></main></section>`}
function safetyForm(type){const f=safetyFormTypes[type];if(!f)return forms();const fields=f.fields.map(([label,kind],i)=>{const name=`field_${i}`;if(kind==='textarea')return `<label class="journal-field">${label}<textarea name="${name}" required></textarea></label>`;if(kind==='select')return `<label class="journal-field">${label}<select name="${name}" required><option value="">Select</option><option>Satisfactory / complete</option><option>Action required</option><option>Not applicable</option></select></label>`;if(kind==='event')return `<label class="journal-field">${label}<select name="${name}" required><option value="">Select</option><option>Accident / injury</option><option>Near miss</option><option>Dangerous occurrence</option><option>Occupational ill health</option><option>Property or environmental incident</option></select></label>`;return `<label class="journal-field">${label}<input name="${name}" type="${kind}" required></label>`}).join("");return `<section class="journal-page">${journalHead(f.title,"forms")}<main class="paper-workflow safety-form-page"><div class="safety-form-emblem"><span>†</span><i></i></div><p>${f.intro}</p><form onsubmit="submitSafetyForm(event,'${type}')"><label class="journal-field">Completed by<input name="worker" value="Dean" required></label><label class="journal-field">Department<select name="department" required><option>Heritage Eggs</option><option>Animals & Production</option><option>Land & Crops</option><option>Maintenance & Fleet</option><option>Estate Operations</option><option>People & Training</option></select></label>${fields}<label class="photo-upload journal-secondary"><input name="photo" type="file" accept="image/*" capture="environment"><span>Add Supporting Photograph</span></label><label class="form-declaration"><input type="checkbox" required><span>I confirm this record is accurate to the best of my knowledge and requires supervisor review.</span></label><button class="journal-primary">Submit for Supervisor Review <span>→</span></button></form></main></section>`}
function submitSafetyForm(event,type){event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget).entries()),s=state(),now=new Date(),reference=`CC-${type.toUpperCase()}-${now.getFullYear()}-${String(Date.now()).slice(-6)}`;if(data.photo&&data.photo.name)data.photo=data.photo.name;else delete data.photo;s.safetyForms=s.safetyForms||[];s.safetyForms.unshift({reference,type,title:safetyFormTypes[type].title,worker:data.worker||"Dean",department:data.department,date:now.toISOString().slice(0,10),createdAt:now.toISOString(),status:"Awaiting supervisor review",data});s.audit=s.audit||[];s.audit.unshift({ts:now.toISOString(),action:"SAFETY_FORM_SUBMITTED",detail:`${reference} · ${safetyFormTypes[type].title}`});save(s);alert(`${safetyFormTypes[type].title} submitted for supervisor review. Reference: ${reference}`);go("forms")}
function formRisk(){return safetyForm("risk")}function formEquipment(){return safetyForm("equipment")}function formCoshh(){return safetyForm("coshh")}function formTraining(){return safetyForm("training")}function formIncident(){return safetyForm("incident")}

function operationalFooter(){const active=view==='home'?'home':(['tasks','task','collect'].includes(view)?'tasks':(view==='journal'||view==='journal-detail'||view==='forms'||view.startsWith('form-')?'journal':'more'));return `<nav class="field-bottom-nav operational-footer"><button class="${active==='home'?'active':''}" onclick="go('home')"><i class="nav-icon nav-home"></i><span>My Day</span></button><button class="${active==='tasks'?'active':''}" onclick="go('tasks')"><i class="nav-icon nav-tasks"></i><span>Tasks</span></button><button class="${active==='journal'?'active':''}" onclick="go('journal')"><i class="nav-icon nav-journal"></i><span>Journal</span></button><button class="${active==='more'?'active':''}" onclick="go('more')"><i class="nav-icon nav-more"></i><span>More</span></button></nav>`}
function decorateOperationalPage(){app.dataset.view=view;const page=app.querySelector('.journal-page');if(!page)return;page.classList.add('crown-cross-operational');const head=page.querySelector('.journal-head');if(head){head.insertAdjacentHTML('beforeend',`<aside class="journal-live-status"><div><b>18°C</b><small>Partly sunny</small></div><div class="journal-alert-crown"><i class="alert-crown"></i><span>1</span></div><div><b>Dean</b><small>Estate Director</small></div></aside>`)}const work=page.querySelector('.paper-workflow');if(work&&!work.querySelector('.page-emblem')&&!work.querySelector('.safety-faith-mark'))work.insertAdjacentHTML('afterbegin',`<div class="page-emblem emblem-${view.replace('form-','form')}"><i></i><span>†</span></div>`);page.insertAdjacentHTML('beforeend',operationalFooter())}
function toggleHouseMenu(){const y=scrollY;houseMenuOpen=!houseMenuOpen;render();requestAnimationFrame(()=>scrollTo(0,y))}function chooseHouse(i){const y=scrollY;selectedHouse=i;houseMenuOpen=false;render();requestAnimationFrame(()=>scrollTo(0,y))}
function collectV40(){return `<section class="journal-page">${journalHead("Egg Collection","task")}<main class="paper-workflow collection"><div class="collection-intro"><small>HERITAGE EGGS</small><h2>Ten-Colour Entry</h2><div class="collection-faith-divider" aria-hidden="true"><span>†</span></div><p>Select the poultry house, then record every heritage egg colour collected.</p></div><div class="house-picker"><button class="house-select ${houseMenuOpen?'open':''}" aria-expanded="${houseMenuOpen}" onclick="toggleHouseMenu()"><span>House ${selectedHouse+1} — ${collections[selectedHouse].replace(' Egg Collection','')}</span><b>⌄</b></button>${houseMenuOpen?`<div class="house-options">${collections.map((x,i)=>`<button class="${i===selectedHouse?'selected':''}" onclick="chooseHouse(${i})"><span>House ${i+1}</span><strong>${x.replace(' Egg Collection','')}</strong></button>`).join('')}</div>`:''}</div><section class="egg-rows">${colours.map((c,i)=>`<div><i class="egg ${c==='Speckled'?'speckled-egg':''}" style="--egg:${eggColours[i]}"></i><strong>${c}</strong><button aria-label="Remove one ${c} egg" onclick="change('${c}',-1)">−</button><input aria-label="${c} egg count" inputmode="numeric" value="${counts[c]}" onchange="counts['${c}']=Math.max(0,+this.value||0);render()"><button aria-label="Add one ${c} egg" onclick="change('${c}',1)">+</button></div>`).join("")}</section><div class="collection-total"><span>Total Eggs</span><strong>${total()}</strong></div><label class="journal-field collection-notes"><strong>Notes</strong><textarea placeholder="Optional collection notes"></textarea></label><label class="photo-upload journal-secondary collection-photo"><input type="file" accept="image/*" onchange="chooseCollectionPhoto(this)"><span>Add Photograph</span><small>Take a new photo or choose from Photos</small></label>${collectionPhoto?`<figure class="photo-preview"><img src="${collectionPhoto.data}" alt="Selected collection photograph"><figcaption>${collectionPhoto.name}</figcaption><button type="button" onclick="collectionPhoto=null;render()">Remove</button></figure>`:``}<div class="collection-actions"><button class="journal-secondary collection-back" onclick="go('task')">Back</button><button class="journal-primary" onclick="submitCollection()">Review & Submit <span>→</span></button></div></main></section>`}
function confirmPreTaskSafety(){const checks=[...document.querySelectorAll('.pretask-checks input')];if(!checks.length||checks.some(x=>!x.checked))return alert('Please confirm every safety statement before continuing.');const s=state(),now=new Date(),reference=`PTS-${String(Date.now()).slice(-7)}`;s.preTaskSafety=s.preTaskSafety||[];s.preTaskSafety.unshift({reference,worker:'Dean',department:'Heritage Eggs',createdAt:now.toISOString(),status:'Confirmed',confirmations:checks.length});s.audit=s.audit||[];s.audit.unshift({ts:now.toISOString(),action:'PRE_TASK_SAFETY_CONFIRMED',detail:`${reference} · Heritage Eggs · Dean`});save(s);go('collect')}
function taskV45(){const checks=["I am fit for work and free from illness or injury.","I have read today’s estate safety procedures and instructions.","PPE is clean, suitable and in good order.","I will handle hens and eggs with care and respect.","I will maintain estate biosecurity standards at all times.","I will report hazards, incidents or concerns without delay."];return `<section class="journal-page">${journalHead("Pre-Task Safety")}<main class="paper-workflow pretask-page"><div class="pretask-heading"><div class="pretask-shield" aria-hidden="true"><i></i></div><small>HERITAGE EGGS</small><h2>Safety First</h2><div class="pretask-divider" aria-hidden="true"><span></span></div><p>Please read and personally confirm every statement before beginning today’s collection.</p></div><div class="journal-checks pretask-checks">${checks.map((x,i)=>`<label><input id="safety-${i}" type="checkbox"><i aria-hidden="true"></i><span>${x}</span></label>`).join("")}</div><p class="pretask-note"><strong>Faithful stewardship</strong><span>Work carefully, protect one another and care for every animal entrusted to the estate.</span></p><div class="pretask-actions"><button class="journal-secondary" onclick="go('home')">Back to My Day</button><button class="journal-primary" onclick="confirmPreTaskSafety()">I Confirm & Continue <span>→</span></button></div></main></section>`}
function concernText(value){return value.replace(/[&<>]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[char]))}function rememberConcernDescription(){concernDescription=document.querySelector('#concern-description')?.value||concernDescription}function toggleConcernLocationMenu(){const y=scrollY;rememberConcernDescription();concernLocationMenuOpen=!concernLocationMenuOpen;render();requestAnimationFrame(()=>scrollTo(0,y))}function chooseConcernLocation(i){const y=scrollY;rememberConcernDescription();concernLocation=i;concernLocationMenuOpen=false;render();requestAnimationFrame(()=>scrollTo(0,y))}function chooseConcernType(type){const y=scrollY;rememberConcernDescription();concernType=type;render();requestAnimationFrame(()=>scrollTo(0,y))}function chooseConcernPhoto(input){const file=input.files&&input.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const y=scrollY;rememberConcernDescription();concernPhoto={name:file.name,data:reader.result};render();requestAnimationFrame(()=>scrollTo(0,y))};reader.readAsDataURL(file)}function submitConcern(){const location=concernLocations[concernLocation],description=document.querySelector('#concern-description')?.value.trim()||'';if(!concernType)return alert('Please select the type of concern.');if(!description)return alert('Please describe the concern before submitting.');const s=state(),now=new Date(),reference=`CON-${String(Date.now()).slice(-7)}`;s.concerns=s.concerns||[];s.concerns.unshift({reference,type:concernType,location,description,photo:concernPhoto?{name:concernPhoto.name,data:concernPhoto.data}:null,worker:'Dean',createdAt:now.toISOString(),status:'Supervisor alerted'});s.audit=s.audit||[];s.audit.unshift({ts:now.toISOString(),action:'FIELD_CONCERN_REPORTED',detail:`${reference} · ${concernType} · ${location}`});save(s);concernType='';concernPhoto=null;concernLocation=0;concernLocationMenuOpen=false;concernDescription='';alert(`Concern submitted. Supervisor alerted. Reference: ${reference}`);go('home')}
function concernV46(){const types=[['welfare','Animal Welfare'],['biosecurity','Biosecurity'],['equipment','Equipment'],['safety','Health & Safety'],['environment','Environment'],['other','Other']];return `<section class="journal-page">${journalHead("Report a Concern")}<main class="paper-workflow concern concern-v46"><div class="concern-heading"><div class="concern-seal" aria-hidden="true"><i>!</i></div><small>ESTATE REPORTING</small><h2>What would you like<br>to report?</h2><div class="pretask-divider" aria-hidden="true"><span></span></div><p>Select the most appropriate category. Urgent concerns will be raised with the responsible estate manager.</p></div><div class="concern-types">${types.map(([key,label])=>`<button class="${concernType===key?'selected':''}" aria-pressed="${concernType===key}" onclick="chooseConcernType('${key}')"><i class="concern-icon concern-${key}" aria-hidden="true"></i><span>${label}</span></button>`).join('')}</div><label class="journal-field concern-field"><strong>Location</strong></label><div class="house-picker concern-location-picker"><button id="concern-location" class="house-select ${concernLocationMenuOpen?'open':''}" aria-expanded="${concernLocationMenuOpen}" onclick="toggleConcernLocationMenu()"><span>${concernLocations[concernLocation]}</span><b>⌄</b></button>${concernLocationMenuOpen?`<div class="house-options">${concernLocations.map((location,i)=>`<button class="${i===concernLocation?'selected':''}" onclick="chooseConcernLocation(${i})"><span>Location</span><strong>${location}</strong></button>`).join('')}</div>`:''}</div><label class="journal-field concern-field"><strong>Description</strong><textarea id="concern-description" placeholder="What happened? Where? Are there immediate risks?">${concernText(concernDescription)}</textarea></label><label class="photo-upload journal-secondary collection-photo"><input type="file" accept="image/*" onchange="chooseConcernPhoto(this)"><span>Add Photograph</span><small>Take a new photo or choose from Photos</small></label>${concernPhoto?`<figure class="photo-preview"><img src="${concernPhoto.data}" alt="Selected concern photograph"><figcaption>${concernPhoto.name}</figcaption><button type="button" onclick="concernPhoto=null;render()">Remove</button></figure>`:''}<div class="concern-actions"><button class="journal-secondary" onclick="go('home')">Back to My Day</button><button class="journal-primary" onclick="submitConcern()">Submit Report <span>→</span></button></div></main></section>`}
function workflowHeading(kind,kicker,title,intro){return `<div class="workflow-heading workflow-${kind}"><div class="workflow-seal" aria-hidden="true"><i></i><span>†</span></div><small>${kicker}</small><h2>${title}</h2><div class="pretask-divider" aria-hidden="true"><span></span></div><p>${intro}</p></div>`}
function tasksV49(){const assigned=[['heritage','HERITAGE EGGS','Pre-Task Safety','Confirm today’s safety statements before collection.','Priority','task'],['collection','EGG COLLECTION','Ten-Colour Entry','Record the complete collection for the selected Heritage House.','Due today','collect'],['welfare','ANIMAL WELFARE','Livestock Checks','Review the scheduled welfare round and record any concern.','Scheduled','concern'],['report','ESTATE REPORTING','Report a Concern','Log any safety, welfare, equipment or estate concern.','Available','concern']];return `<section class="journal-page">${journalHead("Assigned Tasks")}<main class="paper-workflow assigned-tasks-v49">${workflowHeading('tasks','MY ESTATE DAY','Assigned Tasks','Your approved work and priorities for today, presented in the order they should be completed.')}<section class="task-summary-v49"><article><strong>${assigned.length}</strong><span>Assigned today</span></article><article><strong>2</strong><span>Priority actions</span></article><article><strong>Dean</strong><span>Responsible person</span></article></section><section class="assigned-list-v49">${assigned.map(([icon,kicker,title,detail,status,target],i)=>`<button onclick="go('${target}')"><i class="assigned-icon assigned-${icon}"><b>${i+1}</b></i><span><small>${kicker}</small><strong>${title}</strong><em>${detail}</em><mark>${status}</mark></span><b class="assigned-chevron">›</b></button>`).join('')}</section><button class="journal-secondary tasks-home-v49" onclick="go('home')">Back to My Day</button></main></section>`}
function moreV49(){const tools=[['device','DEVICE & ACCESS','Device Setup','Register and approve this estate device.','setup'],['forms','SAFETY & COMPLIANCE','Safety Forms & Records','Risk, equipment, COSHH, training and incident records.','forms'],['concern','ESTATE REPORTING','Report a Concern','Raise safety, welfare and estate issues promptly.','concern'],['signout','SECURE SESSION','Sign Out','Return safely to the Crown & Cross welcome screen.','welcome']];return `<section class="journal-page">${journalHead("More & Settings")}<main class="paper-workflow field-tools-v49">${workflowHeading('tools','CROWN & CROSS ESTATE','Field Tools','Approved tools for safe work, accurate records and secure estate access.')}<section class="field-tools-grid">${tools.map(([icon,kicker,title,detail,target])=>`<button onclick="go('${target}')"><i class="tool-icon tool-${icon}"></i><span><small>${kicker}</small><strong>${title}</strong><em>${detail}</em></span><b>›</b></button>`).join('')}</section><article class="tools-stewardship"><span>†</span><div><small>FAITHFUL STEWARDSHIP</small><strong>Work carefully. Record truthfully. Protect one another.</strong></div></article></main></section>`}
function formsV49(){const s=state(),rows=(s.safetyForms||[]).slice(0,6),icons=['risk','equipment','coshh','training','incident'];return `<section class="journal-page">${journalHead("Safety Forms & Records","more")}<main class="paper-workflow safety-forms-v49">${workflowHeading('forms','SAFETY & COMPLIANCE','Estate Safety Records','Complete the appropriate approved record. Every submission is retained for supervisor review.')}<section class="safety-overview-v49"><article><strong>5</strong><span>Approved forms</span></article><article><strong>${rows.length}</strong><span>Recent records</span></article><article><strong>Secure</strong><span>Audit status</span></article></section><section class="safety-form-list safety-form-list-v49">${Object.entries(safetyFormTypes).map(([k,f],i)=>`<button onclick="go('form-${k}')"><i class="safety-type-icon safety-${icons[i]}"><b>${i+1}</b></i><span><small>APPROVED ESTATE FORM</small><strong>${f.title}</strong><em>${f.intro}</em></span><b>›</b></button>`).join('')}</section><div class="records-title-v49"><span><small>SECURE RECORD</small><h3>Recent Safety Records</h3></span><b>${rows.length}</b></div><section class="journal-records records-v49">${rows.length?rows.map(r=>`<article><strong>${r.title}</strong><span>${r.reference}</span><small>${r.worker} · ${r.date} · ${r.status}</small></article>`).join(''):'<article class="records-empty-v49"><i></i><strong>No safety forms submitted yet</strong><small>Completed forms will appear here and in the main compliance record.</small></article>'}</section><p class="compliance-note compliance-v49"><b>Supervisor review required</b><span>Records support estate compliance and must be reviewed by a competent person where the risk or regulation requires it.</span></p></main></section>`}
function safetyFormV49(type){const f=safetyFormTypes[type];if(!f)return formsV49();const fields=f.fields.map(([label,kind],i)=>{const name=`field_${i}`;if(kind==='textarea')return `<label class="journal-field"><strong>${label}</strong><textarea name="${name}" required></textarea></label>`;if(kind==='select')return `<label class="journal-field"><strong>${label}</strong><select name="${name}" required><option value="">Select</option><option>Satisfactory / complete</option><option>Action required</option><option>Not applicable</option></select></label>`;if(kind==='event')return `<label class="journal-field"><strong>${label}</strong><select name="${name}" required><option value="">Select</option><option>Accident / injury</option><option>Near miss</option><option>Dangerous occurrence</option><option>Occupational ill health</option><option>Property or environmental incident</option></select></label>`;return `<label class="journal-field"><strong>${label}</strong><input name="${name}" type="${kind}" required></label>`}).join('');return `<section class="journal-page">${journalHead(f.title,"forms")}<main class="paper-workflow safety-form-page safety-form-v49">${workflowHeading('form','CROWN & CROSS SAFETY RECORD',f.title,f.intro)}<section class="form-status-v49"><span><small>FORM STATUS</small><strong>New secure record</strong></span><span><small>COMPLETED BY</small><strong>Dean</strong></span></section><form onsubmit="submitSafetyForm(event,'${type}')"><fieldset><legend>Record details</legend><label class="journal-field"><strong>Completed by</strong><input name="worker" value="Dean" required></label><label class="journal-field"><strong>Department</strong><select name="department" required><option>Heritage Eggs</option><option>Animals & Production</option><option>Land & Crops</option><option>Maintenance & Fleet</option><option>Estate Operations</option><option>People & Training</option></select></label></fieldset><fieldset><legend>${f.title}</legend>${fields}</fieldset><label class="photo-upload journal-secondary form-photo-v49"><input name="photo" type="file" accept="image/*"><span>Add Supporting Photograph</span><small>Take a new photo or choose from Photos</small></label><label class="form-declaration declaration-v49"><input type="checkbox" required><span><strong>Accuracy declaration</strong>I confirm this record is accurate to the best of my knowledge and requires supervisor review.</span></label><div class="form-actions-v49"><button type="button" class="journal-secondary" onclick="go('forms')">Back to Safety Forms</button><button class="journal-primary">Submit for Review <span>→</span></button></div></form></main></section>`}
weatherIconClass=function(code,isDay){if(!isDay&&code<=3)return'weather-night';if(code===0)return'weather-clear';if(code<=3)return'weather-cloud';if(code<=48)return'weather-fog';if(code<=67)return'weather-rain';if(code<=77)return'weather-snow';if(code<=82)return'weather-rain';if(code<=86)return'weather-snow';return'weather-storm'};
function render(){app.innerHTML=({standby,welcome,login,setup,home,tasks:tasksV49,journal:journalV47,'journal-detail':journalDetailV48,more:moreV49,task:taskV45,collect:collectV40,concern:concernV46,confirm,forms:formsV49,'form-risk':()=>safetyFormV49('risk'),'form-equipment':()=>safetyFormV49('equipment'),'form-coshh':()=>safetyFormV49('coshh'),'form-training':()=>safetyFormV49('training'),'form-incident':()=>safetyFormV49('incident')}[view]||standby)();app.dataset.view=view;if(!['standby','welcome','login','setup','confirm','home'].includes(view))decorateOperationalPage();enhanceFieldDay();applyLiveWeather()}render();loadLiveWeather();setInterval(()=>{if(view==="standby"||view==="home")render()},60000);setInterval(loadLiveWeather,15*60*1000);if("serviceWorker" in navigator)addEventListener("load",()=>navigator.serviceWorker.register("field-sw.js").catch(()=>{}));
